-- DayFlow Migration 002: Align schema with app data model
--
-- The 001 migration used UUID types for IDs, but the app uses TEXT IDs:
--   • Categories: text slugs ('sys-deep-work', 'cust-social', etc.)
--   • Activities / logs / goals: UUID-formatted text generated by generateId()
--
-- This migration drops and recreates tables with TEXT ids, adds all columns
-- present in the local SQLite schema (schema.ts), and adds the goals table.
-- Safe to run on a fresh Supabase project (no user data yet).
--
-- Run in Supabase Dashboard → SQL Editor, or via: supabase db push

-- ─── Drop old tables (reverse FK order) ─────────────────────────────────────
DROP TABLE IF EXISTS public.ai_usage CASCADE;
DROP TABLE IF EXISTS public.experience_logs CASCADE;
DROP TABLE IF EXISTS public.activities CASCADE;
DROP TABLE IF EXISTS public.goals CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;
DROP TABLE IF EXISTS public.users CASCADE;

-- ─── Users ───────────────────────────────────────────────────────────────────
-- Extends auth.users; id is the Supabase auth UUID stored as TEXT for
-- consistency with the app's user_id fields.
CREATE TABLE public.users (
  id           TEXT PRIMARY KEY,  -- = auth.uid()::text
  email        TEXT NOT NULL,
  settings     JSONB NOT NULL DEFAULT '{
    "day_start": "06:00",
    "quiet_hours_start": "22:00",
    "quiet_hours_end": "08:00",
    "nudge_enabled": true,
    "timezone": "UTC"
  }'::jsonb,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
CREATE POLICY "users_own" ON public.users
  FOR ALL USING (auth.uid()::text = id);

-- ─── Categories ──────────────────────────────────────────────────────────────
-- user_id = NULL → system category (readable by all, not writable by users).
-- user_id = <user> → custom category owned by that user.
CREATE TABLE public.categories (
  id           TEXT PRIMARY KEY,  -- e.g. 'sys-deep-work', 'cust-social'
  user_id      TEXT REFERENCES public.users(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  color        TEXT NOT NULL,
  icon         TEXT NOT NULL,
  is_system    INTEGER NOT NULL DEFAULT 0,
  sort_order   INTEGER NOT NULL DEFAULT 0
);

ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
-- System categories (user_id IS NULL) are readable by everyone
CREATE POLICY "categories_read" ON public.categories
  FOR SELECT USING (user_id IS NULL OR auth.uid()::text = user_id);
CREATE POLICY "categories_write" ON public.categories
  FOR INSERT WITH CHECK (auth.uid()::text = user_id);
CREATE POLICY "categories_update" ON public.categories
  FOR UPDATE USING (auth.uid()::text = user_id);
CREATE POLICY "categories_delete" ON public.categories
  FOR DELETE USING (auth.uid()::text = user_id);

