-- ─── Activities ──────────────────────────────────────────────────────────────
-- Mirrors the local SQLite schema in schema.ts exactly.
-- `deleted = 1` means soft-deleted (hidden from queries but kept for sync).
-- `synced` is intentionally absent — it's a local-only tracking field.
CREATE TABLE public.activities (
  id                  TEXT PRIMARY KEY,
  user_id             TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  activity_type       TEXT NOT NULL DEFAULT 'TIME_BLOCK',
  title               TEXT NOT NULL,
  description         TEXT,
  assigned_date       TEXT,
  start_time          TEXT NOT NULL,
  duration_minutes    INTEGER NOT NULL DEFAULT 0,
  category_id         TEXT REFERENCES public.categories(id),
  is_scheduled        INTEGER NOT NULL DEFAULT 1,
  mindset_prompt      TEXT,
  mindset_overridden  INTEGER NOT NULL DEFAULT 0,
  recurrence_type     TEXT NOT NULL DEFAULT 'NONE',
  recurrence_days     TEXT,
  subtasks            TEXT,  -- JSON array of { id, title, done }
  status              TEXT NOT NULL DEFAULT 'PLANNED',
  priority            TEXT NOT NULL DEFAULT 'MEDIUM',
  actual_start        TEXT,
  actual_end          TEXT,
  goal_id             TEXT,  -- FK added after goals table is created
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  deleted             INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX idx_activities_user_start ON public.activities (user_id, start_time);
CREATE INDEX idx_activities_user_date  ON public.activities (user_id, assigned_date);

ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "activities_own" ON public.activities
  FOR ALL USING (auth.uid()::text = user_id);

-- ─── Experience Logs ─────────────────────────────────────────────────────────
CREATE TABLE public.experience_logs (
  id              TEXT PRIMARY KEY,
  activity_id     TEXT NOT NULL REFERENCES public.activities(id) ON DELETE CASCADE,
  user_id         TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  mood            INTEGER NOT NULL,
  energy          INTEGER NOT NULL,
  completion_pct  INTEGER NOT NULL DEFAULT 0,
  reflection      TEXT,
  would_repeat    TEXT,
  log_phase       TEXT NOT NULL DEFAULT 'AFTER',
  logged_at       TEXT NOT NULL,
  deleted         INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX idx_logs_activity  ON public.experience_logs (activity_id);
CREATE INDEX idx_logs_user      ON public.experience_logs (user_id, logged_at);

ALTER TABLE public.experience_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "logs_own" ON public.experience_logs
  FOR ALL USING (auth.uid()::text = user_id);

-- ─── Goals ───────────────────────────────────────────────────────────────────
CREATE TABLE public.goals (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  title         TEXT NOT NULL,
  metric_type   TEXT NOT NULL DEFAULT 'TIME',
  target_value  INTEGER NOT NULL,
  frequency     TEXT NOT NULL DEFAULT 'DAILY',
  category_id   TEXT REFERENCES public.categories(id),
  specific_days TEXT,
  is_active     INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE INDEX idx_goals_user ON public.goals (user_id, is_active);

ALTER TABLE public.goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "goals_own" ON public.goals
  FOR ALL USING (auth.uid()::text = user_id);

-- ─── Add FK from activities → goals (now that goals table exists) ─────────────
ALTER TABLE public.activities
  ADD CONSTRAINT fk_activities_goal
  FOREIGN KEY (goal_id) REFERENCES public.goals(id) ON DELETE SET NULL;

-- ─── updated_at auto-trigger ─────────────────────────────────────────────────
-- Note: activities and goals store updated_at as TEXT (ISO string set by the app).
-- This trigger keeps the users table updated_at in sync on the Postgres side.
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER users_updated_at
  BEFORE UPDATE ON public.users
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
